export function validateTaxonomy(taxonomy) {
  if (!Array.isArray(taxonomy) || !taxonomy.length) throw new Error('Provide a nonempty category taxonomy.');
  const ids = new Set();
  return taxonomy.map(category => {
    if (!category || !Number.isSafeInteger(category.id) || category.id < 1 || typeof category.name !== 'string' || !category.name.trim()) {
      throw new Error('Each category needs a positive integer ID and nonempty name.');
    }
    if (ids.has(category.id)) throw new Error('Category IDs must be unique.');
    ids.add(category.id);
    return { id: category.id, name: category.name.trim() };
  });
}

export default function prepareTaxonomy({ taxonomyJson }) {
  if (typeof taxonomyJson !== 'string') throw new Error('Provide the category taxonomy as JSON text.');
  let parsed;
  try { parsed = JSON.parse(taxonomyJson); } catch { throw new Error('The category taxonomy must be valid JSON.'); }
  return { taxonomy: validateTaxonomy(parsed) };
}

