export function normalizePosts(posts) {
  if (!Array.isArray(posts)) throw new Error('WordPress must return a post array.');
  const ids = new Set();
  return posts.map(post => {
    if (!post || !Number.isSafeInteger(post.id) || post.id < 1 || typeof post.title?.rendered !== 'string') throw new Error('Every WordPress post needs an ID and rendered title.');
    if (ids.has(post.id)) throw new Error('Repeated post IDs were returned; keep the site stable while listing and try again.');
    ids.add(post.id);
    return { id: post.id, title: post.title.rendered };
  });
}

export default async function collectPages({ firstPosts, firstPagination }, context) {
  const rows = [...firstPosts];
  let pagination = firstPagination, page = 1;
  for (;;) {
    const totalPages = pagination?.totalPages;
    if (totalPages === null) break;
    if (!Number.isSafeInteger(totalPages) || totalPages < 0 || (totalPages < page && !(page === 1 && rows.length === 0 && totalPages === 0))) throw new Error('Invalid WordPress page-count metadata.');
    if (page >= totalPages) break;
    context.signal?.throwIfAborted();
    const response = await context.actions.call('wordpress.list_posts', { page: ++page, perPage: 10 });
    if (!response || !Array.isArray(response.posts)) throw new Error('A WordPress page did not return posts.');
    rows.push(...response.posts);
    pagination = response.pagination;
  }
  return { posts: normalizePosts(rows) };
}

