export default async function updateCategories({ categories }, context) {
  for (const category of categories) {
    context.signal?.throwIfAborted();
    await context.actions.call('wordpress.update_post', { id: category.id, categories: [category.categoryId] });
  }
  return { categories, count: categories.length };
}

