export default async function classifyPosts({ posts, taxonomy }, context) {
  const categories = [];
  for (const post of posts) {
    context.signal?.throwIfAborted();
    categories.push(await context.workflows.call('classify-post', { ...post, taxonomy }));
  }
  return { categories };
}

