export default function preparePost({ id, title, taxonomy }) {
  if (!Number.isSafeInteger(id) || id < 1 || typeof title !== 'string') throw new Error('Provide a post ID and rendered title.');
  const categories = validateTaxonomy(taxonomy);
  return { id, title, categoryList: categories.map(category => category.id + ' = ' + category.name).join('\n'), allowedIds: categories.map(category => category.id) };
}

