export default function validateCategory({ id, completion, allowedIds }) {
  if (typeof completion !== 'string' || !/^[1-9]\d*$/.test(completion.trim())) throw new Error('The model must return exactly one positive category ID.');
  const categoryId = Number(completion.trim());
  if (!Number.isSafeInteger(categoryId) || !allowedIds.includes(categoryId)) throw new Error('The model selected a category outside the configured taxonomy.');
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('The source post ID is invalid.');
  return { id, categoryId };
}
